@CrossOrigin
@RestController
@RequestMapping("/AdmissionQuery")
public class AdmissionQueryRestController extends BaseSpringRestController {
	
	public AdmissionQueryRestController( AdmissionService service ) {
        this.service = service;
    }
    
    /**
     * Handles loading a Admission using a UUID
     * @param		UUID admissionId
     * @return		Admission
     */    
    @GetMapping("/load")
    public Admission load( @RequestParam(required=true) UUID admissionId ) {
    	Admission entity = null;

    	try {  
    		entity = service.getAdmission( new AdmissionFetchOneSummary( admissionId ) );
        }
        catch( Throwable exc ) {
            LOGGER.log( Level.WARNING, "failed to load Admission using Id " + admissionId );
            return null;
        }

        return entity;
    }

    /**
     * Handles loading all Admission business objects
     * @return		Set<Admission>
     */
    @GetMapping("/")
    public List<Admission> loadAll() {                
    	List<Admission> admissionList = null;
        
    	try {
            // load the Admission
            admissionList = service.getAllAdmission();
            
            if ( admissionList != null )
                LOGGER.log( Level.INFO,  "successfully loaded all Admissions" );
        }
        catch( Throwable exc ) {
            LOGGER.log( Level.WARNING,  "failed to load all Admissions ", exc );
        	return null;
        }

        return admissionList;
                            
    }



//************************************************************************    
// Attributes
//************************************************************************
    protected Admission admission = null;
    protected AdmissionService service = null;
    private static final Logger LOGGER = Logger.getLogger(AdmissionQueryRestController.class.getName());
    
}
